 * POST /api/cron/coverage-check
 * Lightweight coverage check — computes coverage without running full discovery.
 * Use this for frequent checks between full discovery runs.
 */
router.post('/coverage-check', async (req: Request, res: Response) => {
  if (!verifyCronAuth(req)) {
    cronLog.warn({ ip: req.ip }, 'Unauthorized cron attempt: coverage-check');
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const { isDupe, jobRunId } = await isDuplicateRun('coverage-check');
  if (isDupe) {
    cronLog.info({ jobRunId }, 'Duplicate coverage-check run detected, skipping');
    return res.status(200).json({
      status: 'skipped',
      reason: 'duplicate_run',
      existingJobRunId: jobRunId,
    });
  }

  const startTime = Date.now();
  try {
    const customerId = req.body?.customerId || 'gravito-internal';
    cronLog.info({ jobRunId, customerId }, 'Starting coverage check');

    const evaluation = await evaluateForSweep(customerId);
    const durationMs = Date.now() - startTime;
    await markJobComplete(jobRunId, 'completed', durationMs);

    // Auto-trigger sweep if critical
    let sweep = null;
    if (evaluation.shouldTrigger && evaluation.priority === 'critical') {
      cronLog.warn({ customerId, reasons: evaluation.reasons }, 'Critical coverage gap — auto-triggering sweep');
      sweep = await triggerSweep(customerId, evaluation, 'coverage_drop');
    }

    return res.json({
      status: 'completed',
      jobRunId,
      durationMs,
      coverage: {
        overallCoverage: evaluation.coverageAtEvaluation,
        shouldTriggerSweep: evaluation.shouldTrigger,
        priority: evaluation.priority,
        reasons: evaluation.reasons,
        affectedSurfaces: evaluation.affectedSurfaces,
      },
      autoSweep: sweep ? {
        surfacesReviewed: sweep.surfacesReviewed,
        issuesFound: sweep.issuesFound,
      } : null,
    });
  } catch (error) {
    const durationMs = Date.now() - startTime;
    const errMsg = error instanceof Error ? error.message : String(error);
    await markJobComplete(jobRunId, 'failed', durationMs, errMsg);
    cronLog.error({ jobRunId, error: errMsg, durationMs }, 'Coverage check failed');
    return res.status(500).json({
      status: 'failed',
      jobRunId,
      error: 'Coverage check failed',
    });
  }
});

/**
 * POST /api/cron/positioning-change-check
 * Checks for positioning changes (business_truth.yaml) and triggers immediate sweep.
 * Run frequently (every 5 minutes) to catch changes fast.
 */

