// =============================================================================
// TYPES
// =============================================================================

export interface RemediationPatch {
  original: string;
  replacement: string;
  reason: string;
  confidence: number; // 0-1
}

export interface RemediationClassification {
  actionType: 'auto_rewrite' | 'patch_applied' | 'flagged_for_review' | 'manual_required' | 'skipped';
  reason: string;
  confidence: number;
}

export interface RemediationInput {
  surfaceId: string;
  surfaceUrl: string;
  content: string;
  issues: Array<{
    id: string;
    severity: string;
    category: string;
    description: string;
    suggestion?: string;
  }>;
  patches: Array<{
    id: string;
    original: string;
    replacement: string;
    reason: string;
  }>;
  score: number;
  truthContext?: string; // Customer's business truth context for LLM
}

export interface RemediationOutput {
  surfaceId: string;
  actionType: string;
  patchesApplied: RemediationPatch[];
  remediatedContent: string | null;
  confidenceScore: number;
  issuesResolved: number;
  issuesRemaining: number;
  requiresReview: boolean;
}

// =============================================================================
// CLASSIFICATION ENGINE
// =============================================================================

/**
 * Classify issues by remediability.
 * 
 * Auto-fixable:
 * - Deprecated term replacement (old product name → new)
 * - Stale year references
 * - Brand voice inconsistencies with clear patches
 * - Forbidden phrase removal
 * 
 * Flagged for review:
 * - Content that needs rewriting (not just find/replace)
 * - Tone/voice adjustments
 * - Claims that need evidence updates
 * 
 * Manual required:
 * - Strategic positioning decisions
 * - New content creation
 * - Visual/design changes
 */
function classifyIssues(issues: RemediationInput['issues'], patches: RemediationInput['patches']): RemediationClassification {
  if (issues.length === 0) {
    return { actionType: 'skipped', reason: 'No issues found', confidence: 1.0 };
  }

  // Count issue types
  const criticalCount = issues.filter(i => i.severity === 'critical').length;
  const highCount = issues.filter(i => i.severity === 'high').length;
  const hasPatches = patches.length > 0;

