  reason: z.string().optional(),                        // One-sentence plain-English explanation
  reason_detail: z.string().optional(),                 // Two-to-three sentence expanded explanation
  affected_dimensions: z.array(z.string()).optional(),  // e.g. ["emotional_mass", "curvature"]
  // Trust Architecture Layer 4 — Economic: data policy version
  data_policy_version: z.string().optional(),           // e.g. "gravito-v1-no-training"
});
export type ReviewContentOutput = z.infer<typeof ReviewContentOutputSchema>;

