        surfaceId: surface.surfaceId,
        error: error instanceof Error ? error.message : String(error),
      }, 'Failed to remediate surface');
      skipped++;
    }
  }

  // Notify owner with summary
  if (autoRewritten > 0 || patchesApplied > 0 || flaggedForReview > 0) {
    await notifyOwner({
      title: `Auto-Remediation Complete: ${autoRewritten + patchesApplied} surfaces fixed`,
      content: [
        `Sweep #${sweepId} remediation results:`,
        `- Auto-rewritten: ${autoRewritten}`,
        `- Patches applied: ${patchesApplied}`,
        `- Flagged for review: ${flaggedForReview}`,
        `- Manual required: ${manualRequired}`,
        `- Skipped: ${skipped}`,
        '',
        flaggedForReview > 0 ? `⚠️ ${flaggedForReview} surfaces need human review.` : '',
      ].filter(Boolean).join('\n'),
    }).catch(() => {});
  }

  log.info({
    sweepId, customerId,
    autoRewritten, patchesApplied, flaggedForReview, manualRequired, skipped,
  }, 'Batch remediation complete');

  return {
    totalSurfaces: surfaceResults.length,
    autoRewritten,
    patchesApplied,
    flaggedForReview,
    manualRequired,
    skipped,
    results,
  };
}
