 * Remediate a surface WITH the mandatory Gravito gate.
 * 
 * Flow:
 * 1. Claude generates remediated content
 * 2. Gravito Gate evaluates the output
 * 3. If PASSED: content is accepted
 * 4. If BLOCKED: re-remediate using Gravito's feedback, then re-gate
 * 5. If still BLOCKED: flag for human review
 * 
 * This is the function that should replace direct calls to remediateSurface.
 */
export async function gatedRemediation(
  sweepId: number,
  customerId: string,
  input: {
    surfaceId: string;
    surfaceUrl: string;
    content: string;
    issues: any[];
    patches: any[];
    score: number;
    truthContext?: string;
  },
  config: Partial<GateConfig> = {},
): Promise<{
  accepted: boolean;
  gateDecision: GateDecision;
  gravitoRunId: string | null;
  remediatedContent: string | null;
  attempts: number;
  gateResults: GateResult[];
}> {
  const cfg = { ...DEFAULT_GATE_CONFIG, ...config };
  const gateResults: GateResult[] = [];
  let attempts = 0;

  // Import remediation
  const { remediateSurface } = await import('./remediation');

  // Step 1: Generate initial remediation
  const initialRemediation = await remediateSurface(sweepId, customerId, {
    surfaceId: input.surfaceId,
    surfaceUrl: input.surfaceUrl,
    content: input.content,
    issues: input.issues,
    patches: input.patches,
    score: input.score,
    truthContext: input.truthContext,
  });

  if (!initialRemediation.remediatedContent) {
    // Nothing to gate — remediation produced no changes
    return {
      accepted: false,
      gateDecision: 'blocked',
      gravitoRunId: null,
      remediatedContent: null,
      attempts: 0,
      gateResults: [],
    };
  }

  // Step 2: Run through Gravito Gate
  attempts++;
  const firstGate = await gravitoGate(
    initialRemediation.remediatedContent,
    input.surfaceId,
    cfg,
  );
  gateResults.push(firstGate);

  if (firstGate.decision === 'passed' || firstGate.decision === 'passed_with_warnings') {
    // ACCEPTED — content passed the gate
    log.info({
      surfaceId: input.surfaceId,
      decision: firstGate.decision,
      score: firstGate.score,
      gravitoRunId: firstGate.gravitoRunId,
    }, 'Gated remediation: ACCEPTED on first pass');

    return {

